before.lib/price.ex:
defmodule Price do
  @doc "Total cents: sum each unit price times its quantity."
  def total(items), do: Enum.sum(for {price, quantity} <- items, do: price * quantity)
end
defmodule Checkout do
  def total(items), do: Price.total(items)
end

